# find connected components of non-bg by color? Let's use flood fill on whole grid
from collections import deque
def comps(g,colors):
    h,w=len(g),len(g[0])
    seen=set()
    res=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] in colors and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); com=[]
                while q:
                    x,y=q.popleft(); com.append((x,y))
                    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and g[nx][ny] in colors and (nx,ny) not in seen:
                            seen.add((nx,ny)); q.append((nx,ny))
                res.append(com)
    return res
