        for p in cs: occ[p[0]][p[1]]=True
    cur_objs={v:[list(c)[:] for c in colcomps[v]] for v,cs in colcomps.items() if v!=bg and not all(len(c)==1 for c in cs)}
    changed=True
    while changed:
        changed=False
        moved_any=False
        for v in sorted(cur_objs):
            cc=cur_objs[v]
            for off in [(-1,-1),(0,0)]:
                nxt=[(r+off[0],c+off[1]) for r,c in cc]
                ok=all(0<=r<H and 0<=c<W and not occ[r][c] for r,c in nxt)
