            if dvis[r*W+c]: continue; dvis[r*W+c]=True
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and not dvis[nr*W+nc]:
                    dvis[nr*W+nc]=True
                    dist[nr,nc]=dd+1
                    hq.heappush(pq,(dd+1,nr,nc))
        noise=[(i,j) for i in range(H) for j in range(W) if inp[i,j]==ncol and dist[i,j]!=999]
        if noise:
            moved_any=True; changed=True
        # compact bounding box of final content and return it as height-preserved output
    # crop bbox
    rows_used=[i for i in range(H) for j in range(W) if not occ[i][j]]; cols_used=[j for i in range(H) for j in range(W) if not occ[i][j]]

